// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("max finds the largest Integer and the largest String", () -> {
        eq(max(List.of(3, 9, 4)), 9);
        eq(max(Set.of("pear", "apple", "zoo")), "zoo");
    });
    test("max of an empty collection throws IllegalArgumentException", () ->
        raises(IllegalArgumentException.class, () -> max(List.<Integer>of())));
    test("max returns the first of equal maxima", () -> {
        var first = new Version(2, 0, "first");
        var second = new Version(2, 0, "second");
        ok(max(List.of(new Version(1, 9, "old"), first, second)) == first);
    });
    test("max works on Betas, whose Comparable comes from Version", () -> {
        List<Beta> betas = List.of(new Beta(1, 2, "1.2-beta"), new Beta(1, 10, "1.10-beta"), new Beta(0, 99, "0.99-beta"));
        Beta newest = max(betas);
        eq(newest.label, "1.10-beta");
    });
    test("clamp keeps a value inside the range and pins one outside it", () -> {
        eq(clamp(5, 1, 10), 5);
        eq(clamp(-3, 1, 10), 1);
        eq(clamp(42, 1, 10), 10);
        eq(clamp(10, 1, 10), 10);
        eq(clamp("m", "c", "k"), "k");
    });
    test("clamp rejects lo above hi", () ->
        raises(IllegalArgumentException.class, () -> clamp(5, 10, 1)));
    test("topN gives the n largest, largest first, ties in encounter order", () -> {
        var picked = topN(List.of(new Version(1, 0, "a"), new Version(3, 0, "b"),
            new Version(2, 0, "c"), new Version(3, 0, "d")), 3);
        eq(picked.stream().map(v -> v.label).toList(), List.of("b", "d", "c"));
    });
    test("topN copes with n of zero or above the size, rejects n < 0, and leaves its input alone", () -> {
        var input = new ArrayList<>(List.of(1, 3, 2));
        eq(topN(input, 5), List.of(3, 2, 1));
        eq(topN(input, 0), List.of());
        eq(input, List.of(1, 3, 2));
        raises(IllegalArgumentException.class, () -> topN(input, -1));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("copyAll copies Integers into a List<Number> and returns the count", () -> {
        List<Number> dst = new ArrayList<>(List.of(1.5));
        eq(copyAll(dst, List.of(1, 2)), 2);
        eq(dst, List.of(1.5, 1, 2));
    });
    test("copyAll into a Set counts only the items it accepted", () -> {
        Set<Object> dst = new HashSet<>(Set.of("a"));
        eq(copyAll(dst, List.of("a", "b", "b")), 1);
        eq(dst, Set.of("a", "b"));
    });
    test("sum adds any mix of Number subtypes, and 0.0 when empty", () -> {
        approx(sum(List.of(1, 2.5, 3L)), 6.5);
        approx(sum(List.of(new BigDecimal("0.25"), new BigDecimal("0.50"))), 0.75);
        approx(sum(List.<Integer>of()), 0.0);
    });
    test("addRange fills a List<Object>, from inclusive, to exclusive", () -> {
        List<Object> sink = new ArrayList<>(List.of("start"));
        addRange(sink, 3, 6);
        eq(sink, List.of("start", 3, 4, 5));
        addRange(sink, 2, 2);
        eq(sink.size(), 4);
    });
    test("addRange rejects a backwards range and adds nothing", () -> {
        List<Number> sink = new ArrayList<>();
        raises(IllegalArgumentException.class, () -> addRange(sink, 5, 4));
        eq(sink, List.of());
    });
    test("copyMatching takes a Predicate<Object> and keeps source order", () -> {
        Predicate<Object> longName = o -> o.toString().length() > 1;
        List<CharSequence> dst = new ArrayList<>();
        List<String> src = List.of("a", "bb", "c", "ddd");
        eq(copyMatching(src, longName, dst), 2);
        eq(dst, List.of("bb", "ddd"));
        eq(src, List.of("a", "bb", "c", "ddd"));
    });
    test("copyMatching into a Set counts only the items it accepted", () -> {
        Set<Object> dst = new HashSet<>(Set.of("bb"));
        eq(copyMatching(List.of("a", "bb", "ddd", "ddd"), o -> o.toString().length() > 1, dst), 1);
        eq(dst, Set.of("bb", "ddd"));
    });
    test("swapEnds swaps the first and last item of any List<?>", () -> {
        var words = new ArrayList<>(List.of("a", "b", "c"));
        swapEnds(words);
        eq(words, List.of("c", "b", "a"));
        var pair = new ArrayList<>(List.of(1, 2));
        swapEnds(pair);
        eq(pair, List.of(2, 1));
    });
    test("swapEnds never writes to a list with under two items", () -> {
        swapEnds(List.of());
        swapEnds(List.of(7));
        var one = new ArrayList<>(List.of("solo"));
        swapEnds(one);
        eq(one, List.of("solo"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("invert groups the keys that share a value", () -> {
        var colours = new LinkedHashMap<String, String>();
        colours.put("ana", "red");
        colours.put("bob", "blue");
        colours.put("cy", "red");
        var inverted = invert(colours);
        eq(inverted, Map.of("red", List.of("ana", "cy"), "blue", List.of("bob")));
        eq(new ArrayList<>(inverted.keySet()), List.of("red", "blue"));
    });
    test("invert keeps values in first-seen order, not sorted", () -> {
        var stock = new LinkedHashMap<String, Integer>();
        stock.put("x", 30);
        stock.put("y", 4);
        stock.put("z", 30);
        stock.put("w", 17);
        eq(new ArrayList<>(invert(stock).keySet()), List.of(30, 4, 17));
        eq(invert(Map.of()), Map.of());
    });
    test("zip pairs items up and stops at the shorter list", () -> {
        eq(zip(List.of(1, 2, 3), List.of("a", "b")), List.of(new Pair<>(1, "a"), new Pair<>(2, "b")));
        eq(zip(List.of(), List.of("a")), List.of());
    });
    test("zip with a type witness pairs Integers and Doubles as Numbers", () -> {
        List<Pair<Number, Number>> pairs = Exercise.<Number, Number>zip(List.of(1, 2), List.of(2.5, 0.5));
        eq(pairs, List.of(new Pair<Number, Number>(1, 2.5), new Pair<Number, Number>(2, 0.5)));
    });
    test("indexBy keys items by the function, in encounter order", () -> {
        var skus = List.of(new Sku("Q7", "quill"), new Sku("A1", "anchor"), new Sku("M3", "mallet"));
        var byCode = indexBy(skus, Sku::code);
        eq(byCode.get("A1").name(), "anchor");
        eq(new ArrayList<>(byCode.keySet()), List.of("Q7", "A1", "M3"));
    });
    test("indexBy throws IllegalStateException naming a duplicate key", () -> {
        var skus = List.of(new Sku("A1", "anchor"), new Sku("Q7", "quill"), new Sku("A1", "awl"));
        var e = raises(IllegalStateException.class, () -> indexBy(skus, Sku::code));
        ok(e.getMessage().contains("A1"), "message names the key: " + e.getMessage());
    });
    test("firstMatch returns the first accepted item, or empty", () -> {
        eq(firstMatch(List.of(3, 8, 12), n -> n % 2 == 0), Optional.of(8));
        eq(firstMatch(List.of(3, 5), n -> n % 2 == 0), Optional.empty());
        Predicate<Object> isText = o -> o instanceof String;
        eq(firstMatch(List.<Object>of(1, "two", "three"), isText), Optional.of("two"));
    });
    test("firstMatch stops pulling items once it finds a match", () -> {
        var pulled = new ArrayList<Integer>();
        Iterable<Integer> source = () -> Stream.of(3, 8, 12, 15).peek(pulled::add).iterator();
        eq(firstMatch(source, n -> n % 2 == 0), Optional.of(8));
        eq(pulled, List.of(3, 8));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("percentOff takes a percentage off and rounds half up to cents", () -> {
        eq(PricingRule.percentOff(10).apply(money("19.99")).toPlainString(), "17.99");
        eq(PricingRule.percentOff(15).apply(money("0.10")).toPlainString(), "0.09");
        eq(PricingRule.percentOff(100).apply(money("42.00")).toPlainString(), "0.00");
    });
    test("percentOff rejects a percentage outside 0..100", () -> {
        raises(IllegalArgumentException.class, () -> PricingRule.percentOff(101));
        raises(IllegalArgumentException.class, () -> PricingRule.percentOff(-1));
    });
    test("amountOff subtracts but never goes below zero", () -> {
        eq(PricingRule.amountOff(money("5")).apply(money("12.5")).toPlainString(), "7.50");
        eq(PricingRule.amountOff(money("5")).apply(money("3.00")).toPlainString(), "0.00");
    });
    test("andThen applies this rule first, then the next one", () -> {
        var percentFirst = PricingRule.percentOff(10).andThen(PricingRule.amountOff(money("5")));
        var amountFirst = PricingRule.amountOff(money("5")).andThen(PricingRule.percentOff(10));
        eq(percentFirst.apply(money("100")).toPlainString(), "85.00");
        eq(amountFirst.apply(money("100")).toPlainString(), "85.50");
    });
    test("floorAt keeps a rule's result from dropping under a minimum", () -> {
        var rule = PricingRule.amountOff(money("50")).floorAt(money("20"));
        eq(rule.apply(money("60")), money("20"));
        eq(rule.apply(money("100")), money("50"));
    });
    test("all chains rules in list order, and an empty list is identity", () -> {
        var rule = PricingRule.all(List.of(PricingRule.percentOff(50), PricingRule.amountOff(money("1"))));
        eq(rule.apply(money("10")).toPlainString(), "4.00");
        eq(PricingRule.all(List.of()).apply(money("7.77")).toPlainString(), "7.77");
        eq(PricingRule.identity().apply(money("1.5")).toPlainString(), "1.5");
    });
    test("Kiosk resolves the clashing defaults as Greeter, then Localized", () ->
        eq(new Kiosk().greeting(), "Hello / Hola"));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("byDeptThenSeniority sorts by dept, then level high to low, then name", () ->
        eq(names(sorted(byDeptThenSeniority())), List.of("Ana", "Cy", "Bo", "Dee", "Eli", "Uma")));
    test("bySalaryNullsLast ascending puts unknown salaries last", () ->
        eq(names(sorted(bySalaryNullsLast(false))), List.of("Dee", "Uma", "Cy", "Ana", "Bo", "Eli")));
    test("bySalaryNullsLast descending still puts unknown salaries last", () ->
        eq(names(sorted(bySalaryNullsLast(true))), List.of("Ana", "Cy", "Uma", "Dee", "Bo", "Eli")));
    test("explicitOrder follows the list and keeps unlisted items after, in original order", () -> {
        var statuses = new ArrayList<>(List.of("done", "zeta", "new", "alpha", "wip", "new"));
        statuses.sort(explicitOrder(List.of("new", "wip", "done")));
        eq(statuses, List.of("new", "new", "wip", "done", "zeta", "alpha"));
    });
    test("explicitOrder works as a Comparator<Object> over mixed types", () -> {
        var items = new ArrayList<Object>(List.of(3, "b", 1, "a"));
        items.sort(Exercise.<Object>explicitOrder(List.of("a", 1)));
        eq(items, List.of("a", 1, 3, "b"));
    });
    test("caseInsensitiveThenNatural ignores case, then puts upper case first", () -> {
        var words = new ArrayList<>(List.of("banana", "apple", "Banana", "cherry", "Apple"));
        words.sort(caseInsensitiveThenNatural());
        eq(words, List.of("Apple", "apple", "Banana", "banana", "cherry"));
        var unique = new TreeSet<>(caseInsensitiveThenNatural());
        unique.addAll(words);
        eq(unique.size(), 5);
    });
    test("isSorted accepts equal neighbours and rejects a descent", () -> {
        ok(isSorted(List.of(1, 2, 2, 3), Comparator.naturalOrder()));
        ok(!isSorted(List.of(1, 3, 2), Comparator.naturalOrder()));
        ok(isSorted(List.<Integer>of(), Comparator.naturalOrder()));
        ok(isSorted(List.of("a", "bb"), Comparator.<Object>comparingInt(o -> o.toString().length())));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("save inserts, then replaces and returns the previous row", () -> {
        var repo = new InMemoryRepository<Customer, Long>();
        eq(repo.save(new Customer(1L, "Ana", "Oslo")), Optional.empty());
        eq(repo.save(new Customer(1L, "Ana B", "Lima")), Optional.of(new Customer(1L, "Ana", "Oslo")));
        eq(repo.findById(1L), Optional.of(new Customer(1L, "Ana B", "Lima")));
        eq(repo.count(), 1);
        eq(repo.findById(2L), Optional.empty());
    });
    test("save rejects an entity with a null id", () -> {
        var repo = new InMemoryRepository<Customer, Long>();
        raises(IllegalArgumentException.class, () -> repo.save(new Customer(null, "Nobody", "Oslo")));
        eq(repo.count(), 0);
    });
    test("findAll and findWhere are in id order, numeric for Long ids", () -> {
        var repo = customers(10, 9, 100, 2);
        eq(repo.project(Customer::id), List.of(2L, 9L, 10L, 100L));
        eq(repo.findWhere(c -> c.city().equals("Oslo")).stream().map(Customer::id).toList(), List.of(2L, 10L, 100L));
        eq(repo.findAll().size(), 4);
    });
    test("the same class serves String ids, in A-Z order", () -> {
        var repo = new InMemoryRepository<Sku, String>();
        repo.save(new Sku("B-7", 3));
        repo.save(new Sku("A-9", 0));
        repo.save(new Sku("A-10", 5));
        eq(repo.project(Sku::id), List.of("A-10", "A-9", "B-7"));
        eq(repo.findById("A-9").map(Sku::stock), Optional.of(0));
    });
    test("saveAll is all or nothing when one entity has a null id", () -> {
        var repo = customers(1);
        var batch = List.of(new Customer(2L, "Bo", "Oslo"), new Customer(null, "?", "Lima"), new Customer(3L, "Cy", "Lima"));
        raises(IllegalArgumentException.class, () -> repo.saveAll(batch));
        eq(repo.project(Customer::id), List.of(1L));
        repo.saveAll(List.of(new Customer(3L, "Cy", "Lima"), new Customer(2L, "Bo", "Oslo")));
        eq(repo.project(Customer::id), List.of(1L, 2L, 3L));
    });
    test("deleteById reports whether a row was removed", () -> {
        var repo = customers(1, 2);
        ok(repo.deleteById(1L));
        ok(!repo.deleteById(1L));
        ok(!repo.deleteById(99L));
        eq(repo.count(), 1);
    });
    test("project accepts a Function over a supertype", () -> {
        var repo = customers(3, 1);
        Function<Object, String> show = o -> o.getClass().getSimpleName();
        eq(repo.project(show), List.of("Customer", "Customer"));
        List<Object> ids = repo.<Object>project(Customer::id);
        eq(ids, List.of(1L, 3L));
    });
    test("page slices id order; past the end is empty; bad arguments throw", () -> {
        var repo = customers(5, 3, 1, 4, 2);
        eq(repo.page(0, 2).stream().map(Customer::id).toList(), List.of(1L, 2L));
        eq(repo.page(1, 2).stream().map(Customer::id).toList(), List.of(3L, 4L));
        eq(repo.page(2, 2).stream().map(Customer::id).toList(), List.of(5L));
        eq(repo.page(3, 2), List.of());
        raises(IllegalArgumentException.class, () -> repo.page(0, 0));
        raises(IllegalArgumentException.class, () -> repo.page(-1, 2));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("stores values of different types and returns them typed", () -> {
        var port = Key.of("port", Integer.class);
        var host = Key.of("host", String.class);
        var ctx = new Context();
        ctx.put(port, 8080);
        ctx.put(host, "example.org");
        int p = ctx.require(port);
        String h = ctx.require(host);
        eq(p, 8080);
        eq(h, "example.org");
    });
    test("a missing key gives empty, or the fallback", () -> {
        var ctx = new Context();
        var retries = Key.of("retries", Integer.class);
        eq(ctx.get(retries), Optional.empty());
        eq(ctx.getOrDefault(retries, 3), 3);
        ctx.put(retries, 5);
        eq(ctx.getOrDefault(retries, 3), 5);
    });
    test("keys with one name but different types are different keys", () -> {
        var ctx = new Context();
        var asNumber = Key.of("timeout", Integer.class);
        var asText = Key.of("timeout", String.class);
        ctx.put(asNumber, 30);
        ctx.put(asText, "30s");
        eq(ctx.get(asNumber), Optional.of(30));
        eq(ctx.get(asText), Optional.of("30s"));
        eq(ctx.get(Key.of("timeout", Integer.class)), Optional.of(30));
    });
    test("require on a missing key throws NoSuchElementException naming it", () -> {
        var ctx = new Context();
        var e = raises(NoSuchElementException.class, () -> ctx.require(Key.of("tenant", String.class)));
        ok(e.getMessage().contains("tenant"), "message: " + e.getMessage());
    });
    test("a wrong-typed value smuggled through a raw key is refused and not stored", () -> {
        var ctx = new Context();
        var port = Key.of("port", Integer.class);
        @SuppressWarnings("rawtypes") Key raw = port;
        raises(ClassCastException.class, () -> ctx.put(raw, "not a number"));
        eq(ctx.get(port), Optional.empty());
        eq(ctx.names(), List.of());
    });
    test("putting null removes the key", () -> {
        var ctx = new Context();
        var user = Key.of("user", String.class);
        ctx.put(user, "ana");
        ctx.put(user, null);
        eq(ctx.get(user), Optional.empty());
        eq(ctx.names(), List.of());
    });
    test("Key rejects primitive types such as int.class", () -> {
        raises(IllegalArgumentException.class, () -> Key.of("port", int.class));
        eq(Key.of("port", Integer.class).name(), "port");
    });
    test("names lists name:Type for every stored key, sorted", () -> {
        var ctx = new Context();
        ctx.put(Key.of("timeout", Integer.class), 30);
        ctx.put(Key.of("host", String.class), "h");
        ctx.put(Key.of("timeout", String.class), "30s");
        ctx.put(Key.of("user", String.class), "ana");
        ctx.put(Key.of("app", String.class), "shop");
        ctx.put(Key.of("retries", Integer.class), 3);
        ctx.put(Key.of("debug", Boolean.class), true);
        eq(ctx.names(), List.of("app:String", "debug:Boolean", "host:String", "retries:Integer",
            "timeout:Integer", "timeout:String", "user:String"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("start passes its input through, and a null input gives empty", () -> {
        eq(Pipeline.<String>start().run("x"), Optional.of("x"));
        eq(Pipeline.<String>start().run(null), Optional.empty());
    });
    test("map steps change the type one step at a time", () -> {
        Pipeline<String, Integer> doubled = Pipeline.<String>start()
            .map(String::trim).map(Integer::parseInt).map(n -> n * 2);
        eq(doubled.run(" 21 "), Optional.of(42));
    });
    test("filter drops items and later steps never see them", () -> {
        var seen = new ArrayList<Integer>();
        var positives = Pipeline.<Integer>start().filter(n -> n > 0).peek(seen::add).map(n -> 100 / n);
        eq(positives.run(0), Optional.empty());
        eq(positives.run(-4), Optional.empty());
        eq(positives.run(4), Optional.of(25));
        eq(seen, List.of(4));
    });
    test("a map that returns null drops the item", () -> {
        var prices = Map.of("A1", 250, "B2", 99);
        var lookup = Pipeline.<String>start().map(prices::get).map(cents -> cents / 100.0);
        eq(lookup.run("B2"), Optional.of(0.99));
        eq(lookup.run("ZZ"), Optional.empty());
    });
    test("flatMap drops items whose function returns empty", () -> {
        var parse = Pipeline.<String>start().map(String::strip).flatMap(Exercise::parseInt);
        eq(parse.run(" 17 "), Optional.of(17));
        eq(parse.run("17a"), Optional.empty());
    });
    test("every step returns a new pipeline, so branches share a prefix safely", () -> {
        var base = Pipeline.<String>start().map(String::strip);
        var upper = base.map(s -> s.toUpperCase(Locale.ROOT));
        var length = base.map(String::length);
        eq(base.run(" ab "), Optional.of("ab"));
        eq(upper.run(" ab "), Optional.of("AB"));
        eq(length.run(" ab "), Optional.of(2));
    });
    test("then runs a second pipeline on what survives the first", () -> {
        Pipeline<Object, String> describe = Pipeline.<Object>start()
            .filter(o -> !o.toString().isEmpty()).map(o -> "<" + o + ">");
        var parseThenDescribe = Pipeline.<String>start().flatMap(Exercise::parseInt).then(describe);
        eq(parseThenDescribe.run("7"), Optional.of("<7>"));
        eq(parseThenDescribe.run("x"), Optional.empty());
    });
    test("runAll keeps the survivors in input order", () -> {
        var quantities = Pipeline.<String>start().flatMap(Exercise::parseInt).filter(n -> n > 0);
        eq(quantities.runAll(List.of("3", "x", "10", "0", "-2", "1")), List.of(3, 10, 1));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

